import { path } from './path'
import { isSupportedNode, type SupportedNode, ts } from './typescript'
import { Diagnostic } from './diagnostic'
import { type FileSystem, TsMorphFileSystemWrapper } from './fs'
import { NOW_FILE_EXTENSION } from './fluent-file'
import type { Diagnostics } from './plugins/context'

export type CompilerOptions = ts.CompilerOptions
export const DEFAULT_COMPILER_OPTIONS: CompilerOptions = {
    noEmit: true,
    lib: ['lib.es5.d.ts'],
    target: ts.ScriptTarget.ES2023,
    module: ts.ModuleKind.NodeNext,
    esModuleInterop: true,
    isolatedModules: true,
    allowJs: true,
    checkJs: false,
    strict: true,
    alwaysStrict: true,
    exactOptionalPropertyTypes: true,
    noEmitOnError: true,
    noFallthroughCasesInSwitch: true,
    noImplicitOverride: true,
    noImplicitReturns: true,
    noImplicitThis: true,
    noImplicitAny: false,
    noUncheckedIndexedAccess: true,
    noUnusedLocals: true,
    noUnusedParameters: true,
    noPropertyAccessFromIndexSignature: true,
    forceConsistentCasingInFileNames: true,
    resolveJsonModule: true,
    skipLibCheck: true,
    skipDefaultLibCheck: true,
    allowImportingTsExtensions: true,
}
const NOW_FILE_INCLUDE_PATTERN = `**/*${NOW_FILE_EXTENSION}`

type ColumnType = 'boolean' | 'number' | 'array' | 'array-optional'

function resolveColumnType(propType: ts.Type): ColumnType | undefined {
    if (propType.isBoolean()) {
        return 'boolean'
    }
    if (propType.isNumber() || propType.isNumberLiteral()) {
        return 'number'
    }
    if (propType.isArray()) {
        return 'array'
    }
    if (propType.isUnion()) {
        const unionTypes = propType.getUnionTypes()
        const hasArray = unionTypes.some((t) => t.isArray())
        if (hasArray) {
            const hasString = unionTypes.some((t) => t.isString())
            return hasString ? 'array-optional' : 'array'
        }
        // Numeric-choice fields (e.g. `state`, `priority`) resolve to a union of number
        // literals (10 | 20 | 30). The raw XML value is always a string, so it must be
        // coerced to a number to satisfy the literal union.
        if (unionTypes.every((t) => t.isNumberLiteral())) {
            return 'number'
        }
    }
    const typeText = propType.getText()
    if (typeText.match(/^\(.*\)\[\]$/s)) {
        return 'array'
    } else if (typeText.match(/^.*\[\]$/)) {
        return 'array-optional'
    }
    return undefined
}

/** Property of `Now.Internal.TableBrand<Table>`, the only union member unique to reference columns. */
const TABLE_BRAND_PROPERTY = '__table__'

/**
 * Returns the table a reference column points at, or undefined when the column is not a reference.
 *
 * `ReferenceColumn({ referenceTable: 'sys_ui_view' })` types its value as
 * `string | Record<'sys_ui_view'> | ExplicitKey<'sys_ui_view'> | TableBrand<'sys_ui_view'>`, and
 * `TableBrand<T>` (`{ readonly __table__: T }`) is admitted by no other column API — list columns
 * resolve to arrays of `Record<T>` and carry no brand. So the literal type of `__table__` establishes
 * both that the column is a reference and which table it references.
 *
 * The brand must be read via `getTypeAtLocation()`: the property's declared type is the
 * uninstantiated type parameter, not the table name.
 */
function resolveReferenceTable(propType: ts.Type, location: ts.Node): string | undefined {
    for (const candidate of propType.isUnion() ? propType.getUnionTypes() : [propType]) {
        if (!candidate.isObject()) {
            continue
        }
        const brand = candidate.getProperty(TABLE_BRAND_PROPERTY)?.getTypeAtLocation(location)
        if (brand?.isStringLiteral()) {
            return String(brand.getLiteralValue())
        }
    }
    return undefined
}

export class Compiler extends ts.Project {
    private readonly rootDir: string
    private readonly sourceFileToRelativeModuleSpecifier: Record<string, string> = {}
    private readonly generatedTableFilePath: string
    private readonly generatedBootstrappedTablesFilePath: string
    private moduleProject: ts.Project | undefined

    constructor(
        private readonly fs: FileSystem,
        {
            rootDir = '/',
            sourceFilePaths = [],
            compilerOptions = DEFAULT_COMPILER_OPTIONS,
            typesDir,
        }: {
            rootDir?: string
            sourceFilePaths?: string[]
            compilerOptions?: CompilerOptions
            typesDir?: string
        } = {}
    ) {
        super({
            compilerOptions,
            fileSystem: new TsMorphFileSystemWrapper(fs),
        })

        this.rootDir = rootDir
        this.generatedTableFilePath = path.join(this.rootDir, '$$GENERATED$$_common_table.ts')
        this.generatedBootstrappedTablesFilePath = path.join(this.rootDir, '$$GENERATED$$_bootstrapped_tables.ts')
        this.addGlobalTableDefinitionFile()
        if (typesDir) {
            this.addTypesTableDeclaration(typesDir)
        }
        // TODO: move this somewhere better, it doesn't work when I put the file contents in packages/core/src/global
        this.addGlobalModuleExtensions()
        this.addFluentSourceFilesAtPaths(sourceFilePaths)
        // FIXME: we need to find a better way to make the compiler aware of available modules
        // FIXME: change how imports are generated without relying on fixMissingImports
        this.addAvailableModules()
    }

    addAvailableModules() {
        const moduleContent = `
        import '@servicenow/sdk/global'
        import '@servicenow/sdk/core'
        import '@servicenow/sdk/automation'
        `
        const generatedAvailableModulesFilePath = path.join(this.rootDir, '$$GENERATED$$_available_modules.ts')
        this.createSourceFile(generatedAvailableModulesFilePath, moduleContent, {
            overwrite: true,
            scriptKind: ts.ScriptKind.TS,
        })
    }

    addGlobalTableDefinitionFile() {
        const tableDefinitionContent = `
import '@servicenow/sdk/global'
import { Table } from '@servicenow/sdk/core'

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
            }

            interface Tables {
            }

            interface ChoiceSetValues {
            }
        }
    }
}
`
        this.createSourceFile(this.generatedTableFilePath, tableDefinitionContent, {
            overwrite: true,
            scriptKind: ts.ScriptKind.TS,
        })
        this.createSourceFile(this.generatedBootstrappedTablesFilePath, tableDefinitionContent, {
            overwrite: true,
            scriptKind: ts.ScriptKind.TS,
        })
    }

    getGeneratedBootstrappedTablesFile(): ts.SourceFile | undefined {
        return this.getSourceFile(this.generatedBootstrappedTablesFilePath)
    }

    /**
     * Loads the project's @types tables.d.ts into the compiler if it exists.
     * This file contains `declare global` augmentation that merges downloaded
     * dependency table types into Now.Internal.Tables.
     */
    addTypesTableDeclaration(typesDir: string): ts.SourceFile | undefined {
        const tablesDeclarationPath = path.join(this.rootDir, typesDir, 'fluent', 'tables.d.ts')
        return this.addSourceFileAtPathIfExists(tablesDeclarationPath)
    }

    addGlobalModuleExtensions() {
        const globalModuleDefinition = `
declare module '*.html' {
    const content: string;
    export default content;
}`

        this.createSourceFile(path.join(this.rootDir, '$$GENERATED$$_module_extensions.ts'), globalModuleDefinition, {
            overwrite: true,
            scriptKind: ts.ScriptKind.TS,
        })
    }

    /**
     * Recursively adds any source files in the specified directory, and returns the added
     * files. Glob patterns can be supplied to control which files are added. This will also
     * resolve the dependencies of the added files. If the directory does not exist, an empty
     * array will be returned.
     */
    addSourceFilesFromDirectory(dir: string, includePatterns: string[], excludePatterns?: string[]): ts.SourceFile[] {
        const excludedFiles = new Set<string>()
        const fsWrapper = new TsMorphFileSystemWrapper(this.fs)
        if (excludePatterns && excludePatterns.length > 0) {
            const excluded = fsWrapper.globSync(excludePatterns, { cwd: dir })
            excluded.forEach((file) => excludedFiles.add(path.resolve(file)))
        }

        const files = [] as ts.SourceFile[]
        const includedFiles = fsWrapper.globSync(includePatterns, { cwd: dir })
        includedFiles.forEach((file) => {
            if (!excludedFiles.has(file)) {
                files.push(this.addSourceFileAtPath(file))
            }
        })

        return files
    }

    /**
     * Recursively adds any .now.ts files in the specified directory, and returns the added
     * files. Glob patterns can be supplied to control which files are added. This will also
     * resolve the dependencies of the added files. If the directory does not exist, an empty
     * array will be returned.
     */
    addFluentSourceFilesFromDirectory(dir: string): ts.SourceFile[] {
        return this.addSourceFilesFromDirectory(dir, [NOW_FILE_INCLUDE_PATTERN])
    }

    addFluentSourceFilesAtPaths(paths: string[]): ts.SourceFile[] {
        return this.addSourceFilesAtPaths(paths).filter((file) => file.getBaseName().endsWith(NOW_FILE_EXTENSION))
    }

    getFluentSourceFilesFromDirectory(dir: string) {
        const directory = this.getDirectoryOrThrow(dir)
        return directory.getDescendantSourceFiles().filter((file) => file.getBaseName().endsWith(NOW_FILE_EXTENSION))
    }

    getDiagnosticsForFluentFile(fileOrPath: string | ts.SourceFile): TypeScriptDiagnostic[] {
        const file = fileOrPath instanceof ts.SourceFile ? fileOrPath : this.getSourceFileOrThrow(fileOrPath)
        if (!file.getFilePath().endsWith(NOW_FILE_EXTENSION)) {
            return []
        }
        return file
            .getPreEmitDiagnostics()
            .map((diagnostic) => {
                try {
                    return new TypeScriptDiagnostic(diagnostic, this.improveMissingPropertiesDiagnostic(diagnostic))
                } catch (e) {
                    return undefined
                }
            })
            .filter((d) => d) as TypeScriptDiagnostic[]
    }

    private improveMissingPropertiesDiagnostic(diagnostic: ts.Diagnostic): string | undefined {
        const messageText = flattenDiagnosticMessage(diagnostic)

        const missingSinglePropertyPattern =
            /Property '([a-z_]+)' is missing in type '{.*}' but required in type 'Data<"([a-z_]+)">'./
        const missingSingleMatch = messageText.match(missingSinglePropertyPattern)
        if (missingSingleMatch) {
            const [_, propertyName, tableName] = missingSingleMatch
            return `Missing mandatory ${tableName} field: ${propertyName}`
        }

        const missingMultiplePropertiesPattern =
            /Type '{.*}' is missing the following properties from type 'Data<"([a-z_]+)">': (.*)\s*$/
        const missingMultiplesMatch = messageText.match(missingMultiplePropertiesPattern)
        if (missingMultiplesMatch) {
            const [_, tableName, properties] = missingMultiplesMatch
            return `Missing mandatory ${tableName} fields: ${properties}`
        }

        return undefined
    }

    getOrCreateSourceFile(path: string, options?: ts.SourceFileCreateOptions): ts.SourceFile {
        return (
            this.getSourceFile(path) ??
            this.addSourceFileAtPathIfExists(path) ??
            this.createSourceFile(path, '', options)
        )
    }

    async visitSupportedNodes(
        node: ts.Node,
        visitor: (node: SupportedNode) => void | Promise<void>,
        unsupportedNodeVisitor?: (node: ts.Node) => void | Promise<void>
    ): Promise<void> {
        if (node.wasForgotten()) {
            return
        }

        if (!isSupportedNode(node)) {
            await unsupportedNodeVisitor?.(node)
            return
        }

        // Surprisingly, forEachChild() is not the same as getChildren().forEach() so we need to
        // collect all the children using forEachChild() and then iterate
        const children: ts.Node[] = []
        node.forEachChild((child) => {
            children.push(child)
        })

        for (const child of children) {
            await this.visitSupportedNodes(child, visitor, unsupportedNodeVisitor)
        }

        await visitor(node)
    }

    private getTableSchemaModule(sourceFile: ts.SourceFile) {
        return sourceFile?.getModule('global')?.getModule('Now')?.getModule('Internal')?.getModule('TableSchemas')
    }

    private getTableInterface(sourceFile: ts.SourceFile) {
        return sourceFile?.getModule('global')?.getModule('Now')?.getModule('Internal')?.getInterface('Tables')
    }

    private getChoiceSetValuesInterface(sourceFile: ts.SourceFile) {
        return sourceFile?.getModule('global')?.getModule('Now')?.getModule('Internal')?.getInterface('ChoiceSetValues')
    }

    interfaceExistsInGlobalDeclaration(tableName: string) {
        const generatedTableFile = this.getSourceFile(this.generatedTableFilePath)
        const tableSchema = this.getTableSchemaModule(generatedTableFile!)
        return tableSchema?.getInterfaces().find((value) => value.getName() === tableName)
    }

    propertyExistsInGlobalDeclaration(tableName: string) {
        const generatedTableFile = this.getSourceFile(this.generatedTableFilePath)
        const tableInterface = this.getTableInterface(generatedTableFile!)
        return tableInterface?.getProperties().find((value) => value.getName() === tableName)
    }

    importExistsInGlobalDeclaration(resolvedModuleSpecifier: string) {
        const generatedTableFile = this.getSourceFile(this.generatedTableFilePath)
        return generatedTableFile
            ?.getImportDeclarations()
            .find((value) => value.getModuleSpecifierValue() === resolvedModuleSpecifier)
    }

    getGeneratedTableFile() {
        return this.getSourceFile(this.generatedTableFilePath)
    }

    addTableInterfacesToGlobalDeclaration(data: { interfaces; properties; imports; namedImports }) {
        const { interfaces, properties, imports, namedImports } = data

        const generatedTableFile = this.getSourceFile(this.generatedTableFilePath)
        const tableSchema = this.getTableSchemaModule(generatedTableFile!)
        const tableInterface = this.getTableInterface(generatedTableFile!)

        tableSchema?.addInterfaces(interfaces)
        tableInterface?.addProperties(properties)
        generatedTableFile?.addImportDeclarations(Object.values(imports))

        namedImports.forEach((i) => {
            i.existingImport.addNamedImport({
                name: i.name,
            })
        })

        Object.keys(imports).forEach((filePath) => {
            this.sourceFileToRelativeModuleSpecifier[filePath] = imports[filePath].moduleSpecifier
        })
    }

    addChoiceSetValues(table: string, field: string, values: (string | number)[]): void {
        const generatedTableFile = this.getSourceFile(this.generatedTableFilePath)
        const choiceSetInterface = this.getChoiceSetValuesInterface(generatedTableFile!)

        const key = `'${table}.${field}'`
        const valueType = values.map((v) => (typeof v === 'number' ? String(v) : `'${v}'`)).join(' | ')

        const existing = choiceSetInterface?.getProperty(key)
        if (existing) {
            existing.setType(valueType)
        } else {
            choiceSetInterface?.addProperty({ name: key, type: valueType })
        }
    }

    removeTableInterfaceFromGlobalDeclaration(sourceFile: string | ts.SourceFile) {
        const filePath = sourceFile instanceof ts.SourceFile ? sourceFile.getFilePath() : sourceFile
        const generatedTableFile = this.getSourceFile(this.generatedTableFilePath)
        const relativeModuleSpecifier = this.sourceFileToRelativeModuleSpecifier[filePath]
        if (relativeModuleSpecifier) {
            const foundDecl = generatedTableFile
                ?.getImportDeclarations()
                .find((v) => v.getModuleSpecifierValue() === relativeModuleSpecifier)
            if (foundDecl) {
                const tables = foundDecl.getNamedImports().map((v) => v.getName())
                const tableSchema = this.getTableSchemaModule(generatedTableFile!)
                const tableInterface = this.getTableInterface(generatedTableFile!)
                tables.forEach((table) => {
                    tableSchema?.getInterface(table)?.remove()
                    tableInterface?.getProperty(table)?.remove()
                })
                foundDecl.remove()
            }
        }
    }

    isGeneratedTableFile(sourceFile: string | ts.SourceFile): boolean {
        const sourcePath = sourceFile instanceof ts.SourceFile ? sourceFile.getFilePath() : sourceFile
        return this.generatedTableFilePath === sourcePath
    }

    // Caches populated by resolveDataTypeProperties() on first access per table.
    private tableColumnTypesCache = new Map<string, Map<string, ColumnType>>()
    private mandatoryColumnsCache = new Map<string, Set<string>>()
    private referenceColumnsCache = new Map<string, Map<string, string>>()

    /**
     * Resolves Data<T> for the given table and populates the column-type coercion,
     * mandatory-columns and reference-columns caches in a single pass.
     */
    private resolveDataTypeProperties(tableName: string): void {
        if (this.tableColumnTypesCache.has(tableName)) {
            return
        }

        const tempFilePath = path.join(this.rootDir, 'src', '$$TEMP_DATA_RESOLVER$$.ts')
        const typeDeclaration = `type T = import('@servicenow/sdk/core').Data<'${tableName}'>`

        const tempSource = this.createSourceFile(tempFilePath, typeDeclaration, {
            overwrite: true,
            scriptKind: ts.ScriptKind.TS,
        })

        try {
            const typeAlias = tempSource.getTypeAlias('T')
            if (!typeAlias) {
                return
            }

            const resolvedType = typeAlias.getType()
            const properties = resolvedType.getProperties()
            const columnTypes = new Map<string, ColumnType>()
            const mandatoryColumns = new Set<string>()
            const referenceColumns = new Map<string, string>()

            properties.forEach((property) => {
                if (!property.isOptional()) {
                    mandatoryColumns.add(property.getName())
                }

                const propType = property.getTypeAtLocation(typeAlias)
                const columnType = resolveColumnType(propType)
                if (columnType) {
                    columnTypes.set(property.getName(), columnType)
                }

                const referenceTable = resolveReferenceTable(propType, typeAlias)
                if (referenceTable) {
                    referenceColumns.set(property.getName(), referenceTable)
                }
            })

            this.tableColumnTypesCache.set(tableName, columnTypes)
            this.mandatoryColumnsCache.set(tableName, mandatoryColumns)
            this.referenceColumnsCache.set(tableName, referenceColumns)
        } finally {
            this.removeSourceFile(tempSource)
        }
    }

    getTableColumnTypes(tableName: string): Map<string, ColumnType> | undefined {
        this.resolveDataTypeProperties(tableName)
        return this.tableColumnTypesCache.get(tableName)
    }

    getMandatoryColumns(tableName: string): Set<string> | undefined {
        this.resolveDataTypeProperties(tableName)
        return this.mandatoryColumnsCache.get(tableName)
    }

    /**
     * Maps each of the table's reference columns to the table it references, including columns
     * inherited through the `extends` chain. Non-reference columns are absent, as are columns whose
     * type cannot be resolved.
     *
     * Distinct from `Plugins.getReferenceColumns()`, which returns only the reference columns a
     * plugin has explicitly declared. This resolves them from the table's schema, so it also covers
     * tables no plugin describes.
     */
    getTableReferenceColumns(tableName: string): Map<string, string> | undefined {
        this.resolveDataTypeProperties(tableName)
        return this.referenceColumnsCache.get(tableName)
    }

    private createModuleProject(fs: FileSystem, tsConfigPath?: string) {
        return new ts.Project({
            fileSystem: new TsMorphFileSystemWrapper(fs),
            ...(tsConfigPath
                ? {
                      tsConfigFilePath: tsConfigPath,
                      // We always want to emit files even if the user config says not to
                      compilerOptions: { noEmit: false },
                  }
                : {
                      compilerOptions: {
                          target: ts.ScriptTarget.ES2022,
                          module: ts.ModuleKind.ES2022,
                          moduleResolution: ts.ModuleResolutionKind.Bundler,
                          allowImportingTsExtensions: true,
                          declaration: false,
                          sourceMap: false,
                          skipDefaultLibCheck: true,
                          skipLibCheck: true,
                      },
                  }),
        })
    }

    compileModule(
        moduleFile: ts.SourceFile,
        fs: FileSystem,
        diagnostics: Diagnostics,
        tsConfigPath?: string
    ): string | undefined {
        if (!this.moduleProject) {
            this.moduleProject = this.createModuleProject(fs, tsConfigPath)
        }
        const modulePath = moduleFile.getFilePath()
        let sourceFile: ts.SourceFile | undefined
        if (tsConfigPath) {
            sourceFile = this.moduleProject.getSourceFile(modulePath)

            if (!sourceFile) {
                diagnostics.error(
                    moduleFile,
                    `File '${path.relative(this.rootDir, modulePath)}' is not included in project. Check your tsconfig: ${path.relative(this.rootDir, tsConfigPath)}`
                )
                return undefined
            }
        } else {
            sourceFile = this.moduleProject.createSourceFile(modulePath, moduleFile.getFullText(), {
                overwrite: true,
                scriptKind: ts.ScriptKind.TS,
            })
        }

        sourceFile.getPreEmitDiagnostics().forEach((diagnostic) => {
            try {
                diagnostics.add(new TypeScriptDiagnostic(diagnostic))
            } catch (e) {
                //ignore
            }
        })

        const emitResult = sourceFile.getEmitOutput()
        emitResult.getDiagnostics().forEach((d) => {
            try {
                const diagnostic = new TypeScriptDiagnostic(d)
                if (diagnostic.level === Diagnostic.Level.Error) {
                    diagnostics.add(diagnostic)
                }
            } catch (e) {
                //ignore
            }
        })

        const output = emitResult.getOutputFiles()[0]
        if (!output) {
            diagnostics.error(moduleFile, `Failed to get emit output for module: ${modulePath}`)
        }

        return output?.getText()
    }

    resetModuleProject(): void {
        this.moduleProject = undefined
    }
}

function flattenDiagnosticMessage(diagnostic: ts.Diagnostic) {
    const message = diagnostic.getMessageText()

    if (typeof message === 'string') {
        return message
    } else {
        const flattenMessage = (msg: ts.DiagnosticMessageChain): string => {
            let result = msg.getMessageText()
            if (msg.getNext()) {
                const next = msg.getNext()
                if (Array.isArray(next)) {
                    result += `\n  ${next.map(flattenMessage).join(' ')}`
                }
            }
            return result
        }
        return flattenMessage(message)
    }
}

export class TypeScriptDiagnostic extends Diagnostic {
    constructor(
        private readonly diagnostic: ts.Diagnostic,
        customMessage?: string
    ) {
        const start = diagnostic.getStart() ?? 0
        const end = start + (diagnostic.getLength() ?? 0)
        const file = diagnostic.getSourceFile()
        const finalMessage = customMessage ?? flattenDiagnosticMessage(diagnostic)

        if (!file) {
            throw new Error(`TypeScript diagnostic does not have a source file (Message: ${finalMessage})`)
        }

        super(
            finalMessage,
            file,
            { start, end },
            diagnostic.getCode(),
            'ts',
            Diagnostic.Level.fromCategory(diagnostic.getCategory())
        )
    }

    public override asTypeScriptDiagnostic(): ts.ts.Diagnostic {
        const { relatedInformation, ...diagnosticWithoutRelated } = this.diagnostic.compilerObject
        return {
            ...diagnosticWithoutRelated,
            messageText: this.message,
        }
    }
}
